 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the color used for the fine lattice lines by their uniform rows/columns.
    votes = Counter()
    for row in grid:
        c, n = Counter(row).most_common(1)[0]
        if n >= 0.8 * w:
            votes[c] += 1
    for j in range(w):
        c, n = Counter(grid[i][j] for i in range(h)).most_common(1)[0]
        if n >= 0.8 * h:
            votes[c] += 1
    line = votes.most_common(1)[0][0]
    rows = [i for i, row in enumerate(grid) if sum(x == line for x in row) >= 0.8 * w]
    cols = [j for j in range(w) if sum(grid[i][j] == line for i in range(h)) >= 0.8 * h]
    bg = Counter(x for row in grid for x in row if x != line).most_common(1)[0][0]
    out = [[bg for _ in range(len(cols)-1)] for _ in range(len(rows)-1)]
    for i in range(len(rows)-1):
        for j in range(len(cols)-1):
            corners = [grid[rows[i]][cols[j]], grid[rows[i]][cols[j+1]],
                       grid[rows[i+1]][cols[j]], grid[rows[i+1]][cols[j+1]]]
            pairs = [(0,1), (2,3), (0,2), (1,3)]
            for a,b in pairs:
                if corners[a] != line and corners[a] == corners[b]:
                    out[i][j] = corners[a]
                    break
    return out
