 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    marks = {color for color, n in counts.items() if n <= h * w * 0.1}

    def dominant(values, excluded=()):
        vals = [x for x in values if x not in excluded]
        if not vals:
            return None, 0
        color, n = Counter(vals).most_common(1)[0]
        return color, n / len(vals)

    # Long, nearly uniform horizontal bands identify the separator color.
    row_candidates = []
    for row in grid:
        color, fraction = dominant(row, marks)
        if color is not None and fraction >= 0.9:
            row_candidates.append(color)
    line = Counter(row_candidates).most_common(1)[0][0]

    rows = []
    for r, row in enumerate(grid):
        color, fraction = dominant(row, marks)
        if color == line and fraction >= 0.9:
            rows.append(r)

    # A separator column is either consistently the line color, or contains
    # one of the rare colored junction markers that interrupt such a column.
    cols = []
    for c in range(w):
        values = [grid[r][c] for r in range(h)]
        line_fraction = sum(x == line for x in values) / h
        if line_fraction >= 0.95 or any(x in marks for x in values):
            cols.append(c)

    bg = Counter(x for row in grid for x in row if x not in marks and x != line).most_common(1)[0][0]
    out = []
    for i in range(len(rows) - 1):
        outrow = []
        for j in range(len(cols) - 1):
            corners = (grid[rows[i]][cols[j]], grid[rows[i]][cols[j + 1]],
                       grid[rows[i + 1]][cols[j]], grid[rows[i + 1]][cols[j + 1]])
            outrow.append(corners[0] if corners[0] in marks and all(x == corners[0] for x in corners) else bg)
        out.append(outrow)

    # Keep only the bounding rectangle of marked output cells.
    occupied = [(r, c) for r, row in enumerate(out) for c, value in enumerate(row) if value != bg]
    if not occupied:
        return [[bg]]
    r0, r1 = min(r for r, _ in occupied), max(r for r, _ in occupied)
    c0, c1 = min(c for _, c in occupied), max(c for _, c in occupied)
    return [row[c0:c1 + 1] for row in out[r0:r1 + 1]]
